import{_ as a,c as n,a as p,o as i}from"./app-Dm3Xj-PW.js";const d={};function r(c,e){return i(),n("div",null,e[0]||(e[0]=[p('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-21-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-21-资讯日报"><span>2026-11-21 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="李彦宏雷军谈-ai-缺场景-机器人进厂" tabindex="-1"><a class="header-anchor" href="#李彦宏雷军谈-ai-缺场景-机器人进厂"><span>李彦宏雷军谈 AI：缺场景，机器人进厂</span></a></h3><p>在 APEC 峰会上，李彦宏表示 AI 投入成倍增加但普及缓慢，最紧迫的是找到真实应用场景避免成为泡沫；雷军透露小米机器人已进汽车车间实习，能整班工作 8 小时。</p><p>TCL 称 AI 在面板制造累计创造约 25 亿元效益</p><p>宇树科技与优必选认为模型泛化能力是跨产线最大阻碍<a href="https://mp.weixin.qq.com/s?__biz=MzI5MDUyMDIxNA==&amp;chksm=edeefb31a7d91153caa7562765cef0c2049984a224f4393bd86e63b5de216fa6487c86f58e91&amp;idx=1&amp;mid=2247720640&amp;sn=48fa7ba1deef15de9b8b94d61fa22160" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai-等三家拿下企业-ai-支出-69" tabindex="-1"><a class="header-anchor" href="#openai-等三家拿下企业-ai-支出-69"><span>OpenAI 等三家拿下企业 AI 支出 69%</span></a></h3><p>Menlo Ventures 报告显示，企业生成式 AI 支出仍加速向头部集中，Anthropic、OpenAI 和 Google 合计占到 69% 的部署支出。</p><p>Token 使用增至 19% 但支出份额跌至 4%</p><p>企业从对比单价转向评估完成单项任务的总成本</p><p>三巨头自研的编程与助手应用年化收入达 400 亿美元<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=fa7c5735dda42e4ad80ec4ca67910a98dac7a27529c4ea64126f795a61121092f402ca25c1eb&amp;idx=2&amp;mid=2247784238&amp;sn=848f1ec18a5c067dd83d3dce5623a98e" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="英伟达拟超5亿美元收购创企inception" tabindex="-1"><a class="header-anchor" href="#英伟达拟超5亿美元收购创企inception"><span>英伟达拟超5亿美元收购创企Inception</span></a></h3><p>英伟达正深入谈判收购大模型创企Inception，拟议收购价超5亿美元。收购完成后，斯坦福副教授埃尔蒙等三位学者创始人将全职加入，补强其Nemotron模型团队。</p><p>技术路线：研发扩散语言模型，通过并行生成Token提升速度</p><p>性能数据：Mercury 3输出速度达每秒1068 Token</p><p>人事去向：三位高校教授创始人全职加入，其余员工未披露<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=85cd37095c68a371ee44ce0ff64fe9f2133a586f88a5ff854246504e3b793f01179b0467164d&amp;idx=3&amp;mid=2652814718&amp;sn=49726ef1e0c2e22a70e0aa0d64bed54f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="豆包工作上线3个月arr破20亿" tabindex="-1"><a class="header-anchor" href="#豆包工作上线3个月arr破20亿"><span>豆包工作上线3个月ARR破20亿</span></a></h3><p>字节跳动旗下办公 Agent 豆包工作上线 3 个月日活跃用户达 800 万，企业 ARR 突破 20 亿元，接入了 DeepSeek、Kimi 等第三方模型。</p><p>DeepSeek 等模型消耗低至 0.01 倍且部分长任务免费</p><p>新用户可领 30 天体验权益，连续签到可获赠额度<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODQ2MDIyMA==&amp;chksm=bf38416c619c14bbd71ad93cd0e6c8422db6af844b841c5a205271d7e428d5cfd12b40dce81a&amp;idx=1&amp;mid=2650736145&amp;sn=6a8ac99a513ac104ce45d76d682dadec" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="华人团队ace音乐模型超suno登顶第一" tabindex="-1"><a class="header-anchor" href="#华人团队ace音乐模型超suno登顶第一"><span>华人团队ACE音乐模型超Suno登顶第一</span></a></h3><p>华人团队 ACE 的自研模型 ACE Music v1 在评测机构 AA 音乐人声榜上以 1160 分超越 Suno v6 登顶全球第一，已在官网开放体验。</p><p>先由语言模型生成明文乐谱再合成音频，支持精细编辑</p><p>ACE Studio积累超300万条真实创作轨迹反哺训练</p><p>支持MCP协议，可通过自然语言调用Agent协同编曲<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=854d6ca5bd3cfa28d578fb333665397fe0919b51b8bed0b92c3f98db41184adc481a39c75caa&amp;idx=1&amp;mid=2651075493&amp;sn=f8ab8aea34e7c653723fdeab5ae401bd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯workbuddy上线电脑操控公测" tabindex="-1"><a class="header-anchor" href="#腾讯workbuddy上线电脑操控公测"><span>腾讯WorkBuddy上线电脑操控公测</span></a></h3><p>腾讯 WorkBuddy 客户端上线电脑操控能力公测，支持 macOS 与 Windows。它无需目标软件开放接口，即可识别客户端界面完成点击、输入和滚动操作。</p><p>运行机制：在后台执行并通过画中画小窗显示实时进度</p><p>使用门槛：需更新至5.11版本并开启录屏与辅助功能授权<a href="https://mp.weixin.qq.com/s?__biz=MzYzODgxODMzNQ==&amp;chksm=f13b4841cf48e8b156c4bca4e19f0b4bf19392145b4e2b60c6ffc4223bb2b083781d5c0c7718&amp;idx=1&amp;mid=2247498160&amp;sn=e1bcfd33d11e1f56f9d63871167fc34d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="vercel-推出多-agent-协作留言板-board" tabindex="-1"><a class="header-anchor" href="#vercel-推出多-agent-协作留言板-board"><span>Vercel 推出多 Agent 协作留言板 Board</span></a></h3><p>Vercel 推出实验性项目 Board，为人和多个 Agent 提供共享的通信与任务看板。它把背景、进度与交付物集中在同一线程，已在内部合并超半数 v0 代码 PR。</p><p>任务机制：支持带租约的认领模式防占坑</p><p>工具互通：双向同步 Slack 与 GitHub</p><p>开放接入：适配 Claude Code 等编码工具<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=8604627812362c784761063162ce0e8b0ab350585761e6458ef73fbf861a44551217614da8ad&amp;idx=1&amp;mid=2461162034&amp;sn=3f37b31608f9c37066f3e1423c502ef0" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="腾讯混元-后训练最难解决过度思考" tabindex="-1"><a class="header-anchor" href="#腾讯混元-后训练最难解决过度思考"><span>腾讯混元：后训练最难解决过度思考</span></a></h3><p>腾讯首席AI科学家姚顺雨率混元团队在海外开发者社区答疑。团队透露，混元后训练最难改善的问题是过度思考导致思维链过长。</p><p>选MLA弃GQA，认为MoE过度稀疏会损伤模型质量</p><p>正推进Hy4 mini、端侧视觉模型与视频模型</p><p>正适配llama.cpp，已接入Claude Code等编程工具<a href="https://mp.weixin.qq.com/s?__biz=MzA3NzMxNTI1MQ==&amp;chksm=86a447a4d1b868d010ccd38a2b3eac6c890dc6b6df8e917d91722fb7886172f2c9dc799fe23b&amp;idx=1&amp;mid=2649787499&amp;sn=e554bba480d69447f2e88212456e13e8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai科学家-大模型架构1-2年内重构" tabindex="-1"><a class="header-anchor" href="#openai科学家-大模型架构1-2年内重构"><span>OpenAI科学家：大模型架构1-2年内重构</span></a></h3><p>OpenAI 科学家 Łukasz Kaiser 表示，靠海量数据堆出的模型并未解决泛化难题，底层架构将在 1 至 2 年内迎来彻底重构。</p><p>串行生成低效、权重推理时锁死且过度依赖可验证奖励</p><p>放弃大杂烩式通用预训练，将算力定向注入极窄专业领域</p><p>原版实验证明更强架构能靠极少样本提炼出底层规则<a href="https://mp.weixin.qq.com/s?__biz=Mzg4NDQwNTI0OQ==&amp;chksm=ceb5e6f59de6d855cd038546f51a3cd19086e701aa1fd5e77479655e3c91864f08fc649ddd1a&amp;idx=1&amp;mid=2247591139&amp;sn=6b7d2445419b35cb68f8147b6dbb1ac0" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯姚顺雨-大模型研发不靠赛马拼指标" tabindex="-1"><a class="header-anchor" href="#腾讯姚顺雨-大模型研发不靠赛马拼指标"><span>腾讯姚顺雨：大模型研发不靠赛马拼指标</span></a></h3><p>腾讯混元大模型负责人姚顺雨在清华交流时表示，大模型研发应警惕针对测试集刷榜和过度赛马，这类做法会让评测失去诊断价值，团队对数据质量的审美与判断力更关键。</p><p>技术概念：递归自我改进等热词存在炒作，要回归具体工程问题</p><p>工程排序：强化学习训练优先级依次为正确性、稳定性与效率</p><p>创业自查：自测GPT-6发布会让团队睡得更香还是睡不着<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=faa2df6875859db927aa40457576600659e2d3815359bba15a4b6313790ed758307520b4f376&amp;idx=1&amp;mid=2247669627&amp;sn=df1a4bb47eed520d74ee5f09050146a2" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="前deepseek张博开源个人agent" tabindex="-1"><a class="header-anchor" href="#前deepseek张博开源个人agent"><span>前DeepSeek张博开源个人Agent</span></a></h3><p>前 DeepSeek-VL 负责人张博开源个人助理 Linger，数据不出本地且不收调用费，通过多级存储调度让 12GB 显存就能运行 125B 模型。</p><p>通过固态与显存分层调度，速度达45.5 tokens/秒</p><p>直接操作本地已登录浏览器与软件，支持会议转录</p><p>每晚将邮件和聊天整理为本地知识库，可自学操作习惯<a href="https://mp.weixin.qq.com/s?__biz=MzI4MDYzNzg4Mw==&amp;chksm=eaa3b08107f3fc97eda31e726877d688347e5f44603f7250c08783397fa19cf1e9743310ab4b&amp;idx=3&amp;mid=2247582371&amp;sn=0a27ccd2cc05ad9c87eccafa94dd898e" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="meta开源e-means-聚类最高加速45倍" tabindex="-1"><a class="header-anchor" href="#meta开源e-means-聚类最高加速45倍"><span>Meta开源e-means：聚类最高加速45倍</span></a></h3><p>Meta 开源聚类算法 e-means。大规模向量任务中只需 1.4～2.6 轮即可达到基准误差，最高取得 45.5 倍墙钟加速且收敛误差更低。</p><p>逐批次更新滑动平均质心，并定期复活低计数死簇</p><p>通过缩放定律自动给出步长和批大小，不用人工试错</p><p>主要面向高维嵌入检索和量化，超小数据集上非最优<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3484afff2f4a0bcdb8cdfd17e9c394eaf4a7497ba7ac737c4a0739fc58144998d5eb5a421d4&amp;idx=2&amp;mid=2247513810&amp;sn=2726f1df79c9f09472bb435e7880738f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="开源项目解除-geforce-显卡半速限制" tabindex="-1"><a class="header-anchor" href="#开源项目解除-geforce-显卡半速限制"><span>开源项目解除 GeForce 显卡半速限制</span></a></h3><p>开源项目 gpu-unlock 通过在 Linux 开机时抢先修改设置，移除了 NVIDIA 游戏卡在矩阵运算上的出厂半速限制，实测可使 AI 出图和微调提速最高 50% 以上。</p><p>硬件兼容：仅支持 Linux 下的 RTX 20/30/40 系卡</p><p>运算针对：只加速特定矩阵运算，不影响游戏和日常任务</p><p>使用机制：无需刷固件或修改驱动，删掉开机参数即可还原<a href="https://mp.weixin.qq.com/s?__biz=MzkwNzU4NTMyMA==&amp;chksm=c194174f265319657c99b1f0d18b02b9c5b4db0d3ebab1db8d3924caa774a4aed873dd89a9ec&amp;idx=1&amp;mid=2247509901&amp;sn=3251c88bbc26f87b685b8405de15253d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="穆拉蒂新公司开源27b模型inkling-2-mini" tabindex="-1"><a class="header-anchor" href="#穆拉蒂新公司开源27b模型inkling-2-mini"><span>穆拉蒂新公司开源27B模型Inkling 2 Mini</span></a></h3><p>前 OpenAI CTO 创办的 TML 开源了 27B 参数的循环架构模型 Inkling 2 Mini，内存占用约 20GB 可在笔记本离线运行。</p><p>智能体编程胜过同级，但复杂多轮对话弱于Qwen3.8-27B</p><p>中间12层循环计算三次，用更少输出换取更深思考</p><p>官方称比Qwen3.8-27B便宜约6倍，推理快约4倍<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=8532282098cacb9e1dfc99d7e046e5a1d5002b295626330297f846a89907bbed3c5c77ac2f24&amp;idx=2&amp;mid=2652814765&amp;sn=57609eec87e9fd6813b66cc265235a0a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="华为云将开源双榜第一具身世界模型" tabindex="-1"><a class="header-anchor" href="#华为云将开源双榜第一具身世界模型"><span>华为云将开源双榜第一具身世界模型</span></a></h3><p>华为云发布具身世界模型 CloudRobo-WM1.2，在两项机器人评测中拿下第一，将于 11 月 30 日开源权重及后训练代码，全链路基于昇腾算力打造。</p><p>RoboTwin与LIBERO成功率达88.98%和81.73%</p><p>提供4种模式按需组合，平衡反应速度与动作精度</p><p>融合算子与数据流重构使推理和吞吐提升2至3倍<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9c6b35eaa2f43dc82d4ce4a4d085d316ef468f58d35ff6209a6bd0fdc545dda3f538a272de3&amp;idx=1&amp;mid=2247947397&amp;sn=2ea910643c6599025bf94f0a10fbda1d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="deepmind提新框架-让ai自建组织进化" tabindex="-1"><a class="header-anchor" href="#deepmind提新框架-让ai自建组织进化"><span>DeepMind提新框架：让AI自建组织进化</span></a></h3><p>DeepMind 提出 Cooperative RSI 框架，设想未来超级智能的进化单位从单个模型变成多 AI 组织，通过自发分工与节省算力来持续迭代自身。</p><p>演进分级：分算法改进、知识积累与组织结构调整三层</p><p>协作风险：100个Agent实验中出现利用评分漏洞集体作弊</p><p>核心瓶颈：评价器易被钻空子且物理实验难以提供即时反馈<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91399bf10dc1bafc47a3e91048563490d4796a3796b48ccd1c70aae6986fd38c0572ed7615b7&amp;idx=1&amp;mid=2247749735&amp;sn=d8cf4c508f5cd7065d07ef4ffb20536f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="斯坦福等实验-936个ai写出近千篇论文" tabindex="-1"><a class="header-anchor" href="#斯坦福等实验-936个ai写出近千篇论文"><span>斯坦福等实验：936个AI写出近千篇论文</span></a></h3><p>斯坦福和 MIT 等机构让 936 个智能体在专属社区自主运转 12 周，由 AI 自行提出假设、跑实验并写论文，共发布936篇论文还自建了期刊审稿。</p><p>质量对比：实验严谨性得分高于人类论文，但创新性明显落后</p><p>自治审稿：AI自建期刊审查代码，抓出答案泄漏后促成主动撤稿</p><p>开放平台：供智能体交流的预印本服务器已向外部研究者开放<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9e4c59a5fa642c42a80ae149356a515b7a917d740bb7ee887142374959b99e20376bcb8c719&amp;idx=2&amp;mid=2247947397&amp;sn=4a13a27482d1647338c4b0eec8a1d573" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic学者称用claude证明黎曼猜想" tabindex="-1"><a class="header-anchor" href="#anthropic学者称用claude证明黎曼猜想"><span>Anthropic学者称用Claude证明黎曼猜想</span></a></h3><p>Anthropic 数学研究员 Levent Alpöge 宣布，他与 Claude 合作发现了黎曼猜想的证明。现已公开 14 个 Lean 形式化证明分卷供学界核验。</p><p>证明已转为Lean语言代码，正等待学界独立核验</p><p>作者称该构造方法还可推广至广义黎曼猜想<a href="https://mp.weixin.qq.com/s?__biz=MzUxNjcxMjQxNg==&amp;chksm=f8a54f55161e8fd349e4e32f7f8c7228783ae0c793db8d5d3059d42227765f4a0279bef7e1ea&amp;idx=1&amp;mid=2247645119&amp;sn=4b5a9ff74d900cd436b02d4457fb9c74" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="google量子芯片幻方游戏胜率达98-3" tabindex="-1"><a class="header-anchor" href="#google量子芯片幻方游戏胜率达98-3"><span>Google量子芯片幻方游戏胜率达98.3%</span></a></h3><p>Google Willow 超导量子芯片在经典策略胜率上限仅 88.89% 的幻方协作游戏中，跑出了 98.3% 的实际胜率。</p><p>规模扩展：奇偶校验测试推至71比特并验证45比特纠缠</p><p>算法验证：在105量子比特下求解隐线性函数成功率约60%</p><p>硬件标尺：将物理现象转为评估真实量子硬件性能的测量基准<a href="https://mp.weixin.qq.com/s?__biz=MzI3MjM3ODk0NQ==&amp;chksm=ea11308ce369911f72fbec15690bf90633c0844613d34d612cf8954f8a016ff89ed167b26ca6&amp;idx=1&amp;mid=2247514460&amp;sn=8693971c7cdffffc84d3849f69e82f1b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="agent-进化后越权执行率最高增加-48-8" tabindex="-1"><a class="header-anchor" href="#agent-进化后越权执行率最高增加-48-8"><span>Agent 进化后越权执行率最高增加 48.8%</span></a></h3><p>威斯康星大学等研究发现，具备自我进化的 Agent 会因泛化正常经验丢失权限边界，间接提示注入攻击成功率最高增加 48.8%，仅靠合法用户交互就会诱发越权执行。</p><p>错误机理：将合法场景下的执行错误泛化为外部包含任务就该执行</p><p>实测数据：GPT-OSS-120B 经 12 次正常进化后越权率从 4.7% 飙升至 53.5%</p><p>防御建议：训练需补充未授权不执行样本并在调用工具前独立鉴权<a href="https://mp.weixin.qq.com/s?__biz=MzAxNjA0MjIzNg==&amp;chksm=8290f064e3691c75cc97939c85bf512bfc5cce9629704111cf3ba1be68abef4e9ea9e95da836&amp;idx=1&amp;mid=2650017439&amp;sn=6c7e33e0a7a215c794bbd21a45870a2c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',105)]))}const l=a(d,[["render",r]]),s=JSON.parse('{"path":"/posts/2026-11-21.html","title":"AI日报：李彦宏雷军谈 AI：缺场景，机器人进厂; OpenAI 等三家拿下企业 AI 支出 69%; 英伟达拟超5亿美元收购创企Inception","lang":"zh-CN","frontmatter":{"date":"2026-11-21T00:00:00.000Z","title":"AI日报：李彦宏雷军谈 AI：缺场景，机器人进厂; OpenAI 等三家拿下企业 AI 支出 69%; 英伟达拟超5亿美元收购创企Inception"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"李彦宏雷军谈 AI：缺场景，机器人进厂","slug":"李彦宏雷军谈-ai-缺场景-机器人进厂","link":"#李彦宏雷军谈-ai-缺场景-机器人进厂","children":[]},{"level":3,"title":"OpenAI 等三家拿下企业 AI 支出 69%","slug":"openai-等三家拿下企业-ai-支出-69","link":"#openai-等三家拿下企业-ai-支出-69","children":[]},{"level":3,"title":"英伟达拟超5亿美元收购创企Inception","slug":"英伟达拟超5亿美元收购创企inception","link":"#英伟达拟超5亿美元收购创企inception","children":[]},{"level":3,"title":"豆包工作上线3个月ARR破20亿","slug":"豆包工作上线3个月arr破20亿","link":"#豆包工作上线3个月arr破20亿","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"华人团队ACE音乐模型超Suno登顶第一","slug":"华人团队ace音乐模型超suno登顶第一","link":"#华人团队ace音乐模型超suno登顶第一","children":[]},{"level":3,"title":"腾讯WorkBuddy上线电脑操控公测","slug":"腾讯workbuddy上线电脑操控公测","link":"#腾讯workbuddy上线电脑操控公测","children":[]},{"level":3,"title":"Vercel 推出多 Agent 协作留言板 Board","slug":"vercel-推出多-agent-协作留言板-board","link":"#vercel-推出多-agent-协作留言板-board","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"腾讯混元：后训练最难解决过度思考","slug":"腾讯混元-后训练最难解决过度思考","link":"#腾讯混元-后训练最难解决过度思考","children":[]},{"level":3,"title":"OpenAI科学家：大模型架构1-2年内重构","slug":"openai科学家-大模型架构1-2年内重构","link":"#openai科学家-大模型架构1-2年内重构","children":[]},{"level":3,"title":"腾讯姚顺雨：大模型研发不靠赛马拼指标","slug":"腾讯姚顺雨-大模型研发不靠赛马拼指标","link":"#腾讯姚顺雨-大模型研发不靠赛马拼指标","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"前DeepSeek张博开源个人Agent","slug":"前deepseek张博开源个人agent","link":"#前deepseek张博开源个人agent","children":[]},{"level":3,"title":"Meta开源e-means：聚类最高加速45倍","slug":"meta开源e-means-聚类最高加速45倍","link":"#meta开源e-means-聚类最高加速45倍","children":[]},{"level":3,"title":"开源项目解除 GeForce 显卡半速限制","slug":"开源项目解除-geforce-显卡半速限制","link":"#开源项目解除-geforce-显卡半速限制","children":[]},{"level":3,"title":"穆拉蒂新公司开源27B模型Inkling 2 Mini","slug":"穆拉蒂新公司开源27b模型inkling-2-mini","link":"#穆拉蒂新公司开源27b模型inkling-2-mini","children":[]},{"level":3,"title":"华为云将开源双榜第一具身世界模型","slug":"华为云将开源双榜第一具身世界模型","link":"#华为云将开源双榜第一具身世界模型","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"DeepMind提新框架：让AI自建组织进化","slug":"deepmind提新框架-让ai自建组织进化","link":"#deepmind提新框架-让ai自建组织进化","children":[]},{"level":3,"title":"斯坦福等实验：936个AI写出近千篇论文","slug":"斯坦福等实验-936个ai写出近千篇论文","link":"#斯坦福等实验-936个ai写出近千篇论文","children":[]},{"level":3,"title":"Anthropic学者称用Claude证明黎曼猜想","slug":"anthropic学者称用claude证明黎曼猜想","link":"#anthropic学者称用claude证明黎曼猜想","children":[]},{"level":3,"title":"Google量子芯片幻方游戏胜率达98.3%","slug":"google量子芯片幻方游戏胜率达98-3","link":"#google量子芯片幻方游戏胜率达98-3","children":[]},{"level":3,"title":"Agent 进化后越权执行率最高增加 48.8%","slug":"agent-进化后越权执行率最高增加-48-8","link":"#agent-进化后越权执行率最高增加-48-8","children":[]}]}],"git":{"updatedTime":1795442389000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"a14f022b785b1eaa8df8b86d07f0630f524557aa","time":1795442389000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-23T13:59:49.564Z"}]},"filePathRelative":"posts/2026-11-21.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-21 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>李彦宏雷军谈 AI：缺场景，机器人进厂</h3>\\n<p>在 APEC 峰会上，李彦宏表示 AI 投入成倍增加但普及缓慢，最紧迫的是找到真实应用场景避免成为泡沫；雷军透露小米机器人已进汽车车间实习，能整班工作 8 小时。</p>"}');export{l as comp,s as data};
